 public function storeOutcome(Request$r,string$id):JsonResponse{$this->enabled();$case=$this->authorized($r,$id,'transition');$d=$r->validate(['version'=>['required','integer','min:1'],'outcome_code'=>['required','string','max:80'],'findings'=>['required','string','max:30000'],'actions'=>['required','array']]);abort_if(DB::table('hr_relation_conflicts')->where('case_id',$id)->where('staff_id',$this->actor($r)->id)->whereIn('status',['declared','confirmed'])->exists(),409,'An actor with a declared or confirmed conflict cannot prepare the outcome.');$oid=(string)Str::uuid();DB::table('hr_relation_case_outcomes')->insert(['id'=>$oid,'case_id'=>$id,'version'=>$d['version'],'outcome_code'=>$d['outcome_code'],'encrypted_findings'=>encrypt($d['findings']),'actions'=>json_encode($d['actions'],JSON_THROW_ON_ERROR),'status'=>'pending_approval','prepared_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->event($id,'outcome_prepared',$case->status,$case->status,'A case outcome was prepared.',['outcome_id'=>$oid,'version'=>$d['version']],$r->user()->id);return response()->json(['status'=>'success','data'=>DB::table('hr_relation_case_outcomes')->select(['id','case_id','version','outcome_code','status'])->find($oid)],201);}
 public function approveOutcome(Request$r,string$id):JsonResponse{$this->enabled();return DB::transaction(function()use($r,$id){$o=DB::table('hr_relation_case_outcomes')->where('id',$id)->lockForUpdate()->first();abort_unless($o,404);$case=$this->authorized($r,$o->case_id,'transition');abort_unless($o->status==='pending_approval',409);abort_if($o->prepared_by===$r->user()->id,409,'Outcome preparer cannot approve the same version.');abort_if(DB::table('hr_relation_conflicts')->where('case_id',$o->case_id)->where('staff_id',$this->actor($r)->id)->whereIn('status',['declared','confirmed'])->exists(),409,'An actor with a conflict cannot approve the outcome.');DB::table('hr_relation_case_outcomes')->where('id',$id)->update(['status'=>'approved','approved_by'=>$r->user()->id,'approved_at'=>now(),'updated_at'=>now()]);$this->event($o->case_id,'outcome_approved',$case->status,$case->status,'The case outcome was independently approved.',['outcome_id'=>$id],$r->user()->id);return response()->json(['status'=>'success','data'=>DB::table('hr_relation_case_outcomes')->select(['id','case_id','version','outcome_code','status','approved_at'])->find($id)]);});}
 public function submitAppeal(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);$case=DB::table('hr_relation_cases')->where('id',$id)->where('company_id',$a->company_id)->first();abort_unless($case,404);$d=$r->validate(['reason'=>['required','string','max:20000'],'evidence_references'=>['nullable','array']]);abort_unless($case->subject_staff_id===$a->id||DB::table('hr_relation_case_participants')->where('case_id',$id)->where('staff_id',$a->id)->whereIn('participant_role',['complainant','respondent'])->exists(),403,'Only an affected participant may appeal.');abort_unless(DB::table('hr_relation_case_outcomes')->where('case_id',$id)->where('status','approved')->exists(),422,'An approved outcome is required before appeal.');abort_if(DB::table('hr_relation_appeals')->where('case_id',$id)->where('appellant_staff_id',$a->id)->where('status','submitted')->exists(),409,'An open appeal already exists for this participant.');$aid=(string)Str::uuid();DB::table('hr_relation_appeals')->insert(['id'=>$aid,'case_id'=>$id,'appellant_staff_id'=>$a->id,'encrypted_reason'=>encrypt($d['reason']),'evidence_references'=>isset($d['evidence_references'])?json_encode($d['evidence_references'],JSON_THROW_ON_ERROR):null,'status'=>'submitted','submitted_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->event($id,'appeal_submitted',$case->status,'appeal','An appeal was submitted.',['appeal_id'=>$aid],$r->user()->id);DB::table('hr_relation_cases')->where('id',$id)->update(['status'=>'appeal','updated_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_relation_appeals')->select(['id','case_id','appellant_staff_id','status','created_at'])->find($aid)],201);}
 public function decideAppeal(Request$r,string$id):JsonResponse{$this->enabled();$d=$r->validate(['decision'=>['required',Rule::in(['upheld','partially_upheld','denied'])],'resolution'=>['required','string','max:20000']]);return DB::transaction(function()use($r,$id,$d){$a=DB::table('hr_relation_appeals')->where('id',$id)->lockForUpdate()->first();abort_unless($a,404);$case=$this->authorized($r,$a->case_id,'transition');abort_unless($a->status==='submitted',409);abort_if($a->submitted_by===$r->user()->id,409);abort_if(DB::table('hr_relation_case_outcomes')->where('case_id',$a->case_id)->where('approved_by',$r->user()->id)->exists(),409,'Original outcome approver cannot decide the appeal.');DB::table('hr_relation_appeals')->where('id',$id)->update(['status'=>$d['decision'],'resolved_by'=>$r->user()->id,'resolved_at'=>now(),'encrypted_resolution'=>encrypt($d['resolution']),'updated_at'=>now()]);DB::table('hr_relation_cases')->where('id',$a->case_id)->update(['status'=>$d['decision']==='denied'?'closed':'reopened','closed_at'=>$d['decision']==='denied'?now():null,'closed_by'=>$d['decision']==='denied'?$r->user()->id:null,'updated_at'=>now()]);$this->event($a->case_id,'appeal_decided',$case->status,$d['decision']==='denied'?'closed':'reopened','The appeal was independently decided.',['appeal_id'=>$id,'decision'=>$d['decision']],$r->user()->id);return response()->json(['status'=>'success','data'=>DB::table('hr_relation_appeals')->select(['id','case_id','status','resolved_at'])->find($id)]);});}
 public function transition(Request$r,string$id):JsonResponse{$this->enabled();$case=$this->authorized($r,$id,'transition');$d=$r->validate(['to'=>['required',Rule::in(['investigation','hearing','decision','closed','appeal','reopened'])],'reason'=>['required','string','max:10000'],'evidence_references'=>['nullable','array']]);$allowed=['open'=>['investigation','closed'],'investigation'=>['hearing','decision','closed'],'hearing'=>['decision','closed'],'decision'=>['closed','appeal'],'closed'=>['appeal','reopened'],'appeal'=>['closed'],'reopened'=>['investigation','closed']];abort_unless(in_array($d['to'],$allowed[$case->status]??[],true),409);if($d['to']==='closed')abort_if(DB::table('hr_relation_case_team')->where('case_id',$id)->where('status','pending_approval')->exists(),409,'Pending case-team access decisions must be resolved before closure.');DB::transaction(function()use($r,$id,$case,$d){DB::table('hr_relation_cases')->where('id',$id)->update(['status'=>$d['to'],'closed_at'=>$d['to']==='closed'?now():null,'closed_by'=>$d['to']==='closed'?$r->user()->id:null,'updated_at'=>now()]);$this->event($id,'status_changed',$case->status,$d['to'],$d['reason'],$d['evidence_references']??[],$r->user()->id);});return response()->json(['status'=>'success','data'=>DB::table('hr_relation_cases')->select(['id','case_number','status','closed_at'])->find($id)]);}
 public function legalHold(Request$r,string$id):JsonResponse{$this->enabled();$case=$this->authorized($r,$id,'legal_hold');$d=$r->validate(['enabled'=>['required','boolean'],'reason'=>['required','string','max:4000']]);if(!$d['enabled']){$last=DB::table('hr_relation_case_events')->where('case_id',$id)->where('event_type','legal_hold_applied')->latest('occurred_at')->first();abort_unless($case->legal_hold&&$r->user()->can('hr.relations.case-admin'),403,'Only a restricted case administrator may release legal hold.');abort_if($last?->actor_user_id===$r->user()->id,409,'The actor who applied legal hold cannot release it.');}DB::transaction(function()use($r,$id,$case,$d){DB::table('hr_relation_cases')->where('id',$id)->update(['legal_hold'=>$d['enabled'],'updated_at'=>now()]);$this->event($id,$d['enabled']?'legal_hold_applied':'legal_hold_released',$case->status,$case->status,$d['reason'],[],$r->user()->id);});return response()->json(['status'=>'success']);}
 private function authorized(Request$r,string$id,string$capability):object{$a=$this->actor($r);$case=DB::table('hr_relation_cases')->where('id',$id)->where('company_id',$a->company_id)->first();abort_unless($case,404);$admin=$r->user()->can('hr.relations.case-admin');if(!$admin){$member=DB::table('hr_relation_case_team')->where('case_id',$id)->where('staff_id',$a->id)->where('status','active')->whereDate('effective_from','<=',now())->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',now()))->first();abort_unless($member&&in_array($capability,json_decode($member->capabilities,true)?:[],true),403,'Explicit active case-team access is required.');}if($r->route()?->getActionMethod()==='show')activity('hr-relations-sensitive-access')->causedBy($r->user())->withProperties(['case_id'=>$id,'company_id'=>$case->company_id,'access'=>'detail_decrypted','case_admin'=>$admin,'ip'=>$r->ip()])->log('restricted_case_viewed');return$case;}private function event(string$id,string$type,?string$from,?string$to,string$details,array$evidence,string$actor):void{$payload=['type'=>$type,'from'=>$from,'to'=>$to,'details'=>$details,'evidence'=>$evidence,'actor'=>$actor,'at'=>now()->toIso8601String()];DB::table('hr_relation_case_events')->insert(['id'=>(string)Str::uuid(),'case_id'=>$id,'event_type'=>$type,'from_status'=>$from,'to_status'=>$to,'encrypted_details'=>encrypt($details),'evidence_references'=>json_encode($evidence,JSON_THROW_ON_ERROR),'event_checksum'=>hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)),'actor_user_id'=>$actor,'occurred_at'=>now()]);}private function actor(Request$r):Staff{return Staff::query()->where('user_id',$r->user()->id)->firstOrFail();}private function enabled():void{abort_unless(config('hr.features.relations_safety',false),409,'HR relations and safety writes are not enabled.');}
}
